CREATE TABLE IF NOT EXISTS `Vehicle` (`id` TEXT NOT NULL, `vin` TEXT, `name` TEXT NOT NULL, `simulated` INTEGER NOT NULL, `supported` TEXT NOT NULL, `lastSeen` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `Trip` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `started` INTEGER NOT NULL, `scenario` TEXT NOT NULL, `duration` INTEGER NOT NULL, `distance` REAL NOT NULL, `maxSpeed` REAL NOT NULL, `supported` TEXT NOT NULL, `status` TEXT NOT NULL, `routeOffsetKm` REAL, `vehicleId` TEXT NOT NULL DEFAULT 'legacy', `avgCoolant` REAL, `avgOil` REAL, `avgTrim` REAL, `avgVoltage` REAL, `avgLoad` REAL, `warmupMs` INTEGER, `fuelPer100` REAL, `ambientC` REAL, `comparableSamples` INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS `Sample` (`tripId` INTEGER NOT NULL, `elapsed` INTEGER NOT NULL, `timestamp` INTEGER NOT NULL, `speed` REAL NOT NULL, `rpm` INTEGER, `coolant` REAL, `intake` REAL, `voltage` REAL, `throttle` REAL, `distance` REAL NOT NULL, `latitude` REAL NOT NULL, `longitude` REAL NOT NULL, `engineLoad` REAL, `oilC` REAL, `manifoldKpa` REAL, `baroKpa` REAL, `fuelLh` REAL, `stft` REAL, `ltft` REAL, `timing` REAL, `maf` REAL, `speedPresent` INTEGER NOT NULL DEFAULT 1, `simulated` INTEGER NOT NULL DEFAULT 1, `hasLocation` INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(`tripId`, `elapsed`), FOREIGN KEY(`tripId`) REFERENCES `Trip`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `TripEvent` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `tripId` INTEGER NOT NULL, `elapsed` INTEGER NOT NULL, `title` TEXT NOT NULL, FOREIGN KEY(`tripId`) REFERENCES `Trip`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_TripEvent_tripId` ON `TripEvent` (`tripId`);
CREATE TABLE IF NOT EXISTS `DiagnosticSnapshot` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `vehicleId` TEXT NOT NULL, `capturedAt` INTEGER NOT NULL, `codes` TEXT NOT NULL, `freezeFrame` TEXT NOT NULL, `simulated` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
